suppressPackageStartupMessages({library(dplyr);library(stringr);library(readr)})
n <- read_csv("data/ABRS_Myrtaceae_2026/data.csv", col_types = cols(.default = "c"))
cat("rows", nrow(n), " taxa", n_distinct(n$taxon_name), "\n"); print(n %>% group_by(family) %>% summarise(taxa = n_distinct(taxon_name), rows = n()), n = 50)
ctx <- c("commonness_qualifier","leaf_division","entity_measured","population_region","plant_organ_measured","phenological_stage","trait_scoring_method","scoring_certainty")
k <- c("taxon_name","trait_name","value_type","measurement_range", ctx)
d <- n %>% filter(!is.na(value_type)) %>% count(across(all_of(k))) %>% filter(n > 1)
cat("duplicate keys (taxon x trait x value_type x range x contexts):", nrow(d), "\n"); print(head(d, 20))
chr <- as.matrix(n %>% select(value, value_description))
cat("digit-hyphen-digit cells:", sum(str_detect(chr, "[0-9]\\s*[-–]\\s*[0-9]"), na.rm = TRUE), "  empty-set marker:", sum(str_detect(chr, "∅"), na.rm = TRUE), "\n")
ft <- n %>% filter(trait_name %in% c("flowering_time","fruiting_time")); cat("calendar values not 12 y/n:", sum(!str_detect(ft$value, "^[yn]{12}$")), "\n")
tr <- names(yaml::read_yaml("config/traits.yml")$traits$elements)
m <- yaml::read_yaml("data/ABRS_Myrtaceae_2026/metadata.yml"); mt <- sapply(m$traits, function(x) x$trait_name)
cat("metadata trait_names not in traits.yml:", paste(setdiff(mt, tr), collapse = ", "), "\n")
num <- n %>% filter(value_type %in% c("minimum","maximum","mean"), trait_name %in% mt) %>% mutate(v = suppressWarnings(as.numeric(value)))
cat("non-numeric numeric values:", sum(is.na(num$v)), "\n")
